local StoreItemType = {
    Goods = 1,
    Diamond = 2
}

local NotEnough = "<color=#FF3131>%s</color>"

local StoreItemDetailsDialog = Class("StoreItemDetailsDialog")

function StoreItemDetailsDialog:__init()
    self.storeGoodsDojo = nil
    self.isGift = nil
    self.curBuyNum = nil --当前购买数量
    self.prices = nil
end

function StoreItemDetailsDialog:__delete()
    self.storeGoodsDojo = nil
    self.curBuyNum = nil
    self.isGift = nil
    self.prices = nil
end

function StoreItemDetailsDialog:Awake()


end

function StoreItemDetailsDialog:OnFocus(focus)
    if focus then
        GameUtils.UpdateNavBarShowState(false, false)
    end
end

function StoreItemDetailsDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.storeGoodsDojo = self.controller.Argument.parameters.ItemData
        self.openId = self.controller.Argument.parameters.OpenId
        --printInfo(" self.openId" .. tostring(self.openId))
        if self.storeGoodsDojo.currency ~= nil then
            self.curDataType = StoreItemType.Diamond
        else
            self.curDataType = StoreItemType.Goods
        end
        self.isGift = false

        if self.curDataType == StoreItemType.Goods then
            self.prices = {}
            for i, v in pairs(self.storeGoodsDojo.prices) do
                local tb = {}
                tb.id = v.currency
                tb.original = v.original
                tb.current = v.current
                table.insert(self.prices, tb);
            end
            self.curBuyId = self.prices[1].id

        elseif self.curDataType == StoreItemType.Diamond then
            self.prices = {}
            local tb = {}
            tb.id = self.storeGoodsDojo.currency
            tb.current = self.storeGoodsDojo.price
            tb.original = 0
            table.insert(self.prices, tb)
            self.curBuyId = self.prices[1].id
        end
        --printInfo("_ self.prices__" .. table.dump(self.prices))
        self:RefreshState()
    end))

    return coWait
end

function StoreItemDetailsDialog:RefreshState()
    self:RefreshStateTop()
    self:RefreshStateCenter()
    self:RefreshStateBottom()
end

function StoreItemDetailsDialog:RefreshStateTop()
    if not StoreUtils.ProductHasTitle(self.storeGoodsDojo) then
        KTool.SetActive(self.Discount.gameObject, false)
    else
        KTool.SetActive(self.Discount.gameObject, true)
        KTool.GetGameObject("Text", self.Discount.transform):GetComponent(typeof(Text)).text = self.storeGoodsDojo.iconTitle
    end
    if self.isGift then
        KTool.SetActive(self.GoodNode.gameObject, false)
        --self.GiftImage:loadPath
    else
        KTool.SetActive(self.GoodNode.gameObject, true)

        local goodNodeMB = GetLuaBehaviour(self.GoodNode.gameObject, GoodsNodeMBPath)
        if not KTool.IsNull(goodNodeMB) then
            goodNodeMB:Init()
            goodNodeMB.Env:Reload({ goodsId = self.storeGoodsDojo.goodsId, isShowNo = true,
                                    text = string.format('x%d', checkInt(self.storeGoodsDojo.num)) })
        end
    end

    KTool.SetActive(self.StockTitle, self.curDataType == StoreItemType.Goods)

    if self.curDataType == StoreItemType.Goods then
        if self.storeGoodsDojo.stock == -1 then
            KTool.GetGameObject("Text", self.StockTitle.transform):GetComponent(typeof(Text)).text = "∞"
        else
            KTool.GetGameObject("Text", self.StockTitle.transform):GetComponent(typeof(Text)).text = string.format("%d/%d", self.storeGoodsDojo.currentStock, self.storeGoodsDojo.stock)
        end
    end

    local BG = KTool.GetGameObject("BG", self.controller.gameObject.transform)
    UIEventProxy.Create(BG.gameObject).onPointerClick = function()
        UIModule.CloseDialog(self.controller)
    end
end

function StoreItemDetailsDialog:RefreshStateCenter()
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    printInfo(self.storeGoodsDojo.goodsId)
    local vo = goodsConfMgr:GetGoodsVoById(self.storeGoodsDojo.goodsId)
    --printInfo("___" .. table.dump(vo))
    self.Desc.text = vo.desc
    self.Name.text = vo.name
    KTool.GetGameObject("OwnNum", self.ownNumInfo.transform):GetComponent(typeof(Text)).text = localize("已有_num_",{_num_ = GoodsUtils.GetThingNo(self.storeGoodsDojo.goodsId)})
    KTool.SetActive(self.BuyNum.gameObject, self.curDataType == StoreItemType.Goods)
end

