---根据数量改变价格
function StoreItemDetailsDialog:GetCurPrice()
    local curPrice = KTool.GetGameObject("CurPrice", self.PriceInfo.transform)
    --local photoPath = goodsConfMgr:GetPhotoPathById(self.curBuyId)
    local curPriceT = {}
    for i, v in pairs(self.prices) do
        if self.curBuyId == v.id then
            curPriceT = v
            break
        end
    end
    if not KTool.IsNull(curPrice) then
        
        local num = GoodsUtils.GetThingNo(self.curBuyId)
        local total = checkInt(self.curBuyNum) * checkInt(curPriceT.current)
        curPrice:GetComponent(typeof(Text)).text = num >= total and tostring(total) or string.format(NotEnough, total)
        --printInfo("__prices__" .. table.dump(self.storeGoodsDojo.prices))
        --KTool.GetGameObject("Icon", curPrice.transform):GetComponent(typeof(ImageAlterable)):LoadSprite(photoPath)
    end
    local OriginalPrice = KTool.GetGameObject("OriginalPrice", self.PriceInfo.transform)
    if checkInt(curPriceT.original) == 0 then
        KTool.SetActive(OriginalPrice.gameObject, false)
    else
        OriginalPrice:GetComponent(typeof(Text)).text = tostring(checkInt(self.curBuyNum) * checkInt(curPriceT.original))
    end
end

function StoreItemDetailsDialog:OnAddBuyNum()
    self.curBuyNum = self.curBuyNum + 1
    if checkInt(self.storeGoodsDojo.stock) <= 0 and self.curBuyNum >= 99 then
        self.curBuyNum = 99
    else

        if self.storeGoodsDojo.stock > 0 and self.curBuyNum > self.storeGoodsDojo.currentStock then
            self.curBuyNum = self.storeGoodsDojo.currentStock
        else
        end
    end
    self.InputField.text = tostring(self.curBuyNum)
    self:GetCurPrice()
end

function StoreItemDetailsDialog:OnMinusBuyNum()
    self.curBuyNum = self.curBuyNum - 1
    if self.curBuyNum <= 1 then
        self.curBuyNum = 1
    end
    self.InputField.text = tostring(self.curBuyNum)
    --printInfo("CurMinus")
    self:GetCurPrice()
end
